      background: rgba(255,255,255,.15);
      border: 1px solid rgba(255,255,255,.3);
      border-radius: 8px;
      padding: 6px 14px;
      text-align: right;
    }
    .dashboard-header .date-badge .date-text { font-size: 1rem; font-weight: 600; }
    .dashboard-header .date-badge .date-label { font-size: .75rem; opacity: .75; }

    /* ── KPI Cards ── */
    .kpi-card {
      background: #fff;
      border-radius: 12px;
      padding: 18px 20px;
      box-shadow: 0 1px 4px rgba(0,0,0,.08);
      border-left: 4px solid var(--green-mid);
      height: 100%;

